import { db } from './db';

export type Customer = { id: number; email: string; name: string };
const cache = new Map<number, Customer>();

export async function warmCache() {
  const rows = await db.query<Customer>('SELECT id, email, name FROM customers WHERE active = 1');
  for (const c of rows) cache.set(c.id, c);
}

export async function getCustomer(id: number | string): Promise<Customer> {
  if (cache.has(id as number)) return cache.get(id as number)!;
  const [c] = await db.query<Customer>('SELECT id, email, name FROM customers WHERE id = ? AND active = 1', [id]);
  return c;
}
```

